@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--bg:#080b1b;--panel:#0e1327;--panel2:#11182d;--line:#252c45;--text:#f4f3ff;--muted:#7f88a7;--cyan:#5be6e3;--pink:#ff5baf;--yellow:#ffe666;--mono:'DM Mono',monospace;--sans:'Space Grotesk',sans-serif}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:var(--sans);overscroll-behavior:none}body{background-image:radial-gradient(ellipse at 48% -15%,#182248 0%,transparent 42%),linear-gradient(120deg,rgba(58,74,134,.06) 1px,transparent 1px),linear-gradient(rgba(58,74,134,.06) 1px,transparent 1px);background-size:auto,36px 36px,36px 36px}.shell{max-width:1450px;margin:auto;padding:0 56px}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(115,132,191,.15)}.brand{font-size:17px;font-weight:700;letter-spacing:.11em;color:#f8f6ff;text-decoration:none;display:flex;align-items:center;gap:12px}.brand-mark{font-size:23px;color:var(--cyan);transform:rotate(-25deg);display:inline-block;text-shadow:0 0 16px #36ded7}.brand-light{font-weight:400;color:#9da7c3;margin-left:4px}.top-note,.eyebrow,.level-chip,.sound-btn,.key-hint,.board-foot,.corner-tag,.section-heading,.memory-labels,.memory-readout,.intel-line,.control-row,.panel-bottom,.footer{font-family:var(--mono);letter-spacing:.07em}.top-note{font-size:10px;color:#727d9e;letter-spacing:.16em}.live-dot,.chip-dot{display:inline-block;width:6px;height:6px;background:var(--cyan);border-radius:50%;box-shadow:0 0 9px var(--cyan);margin-right:8px}.separator{color:#39425f;margin:0 10px}.sound-btn{border:1px solid #29324e;background:#10162b;color:#9da8c7;border-radius:4px;padding:10px 12px;font-size:10px;letter-spacing:.11em;cursor:pointer}.sound-btn:hover{border-color:var(--cyan);color:var(--cyan)}#soundIcon{font-size:14px;color:var(--cyan);padding-right:7px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 316px;gap:40px;padding:34px 0 28px}.arena-head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:16px}.eyebrow{font-size:10px;color:#7e89a8;letter-spacing:.16em}.arena-title .eyebrow b{color:var(--cyan);font-weight:500;margin-left:7px}.arena-title h1{font-size:26px;line-height:1;margin:7px 0 0;font-weight:700;letter-spacing:.045em}.arena-title h1 em{font-style:normal;color:var(--cyan)}.level-chip{font-size:9px;color:#aab3cd;border:1px solid #29314c;padding:8px 11px;border-radius:3px;letter-spacing:.1em;margin-bottom:1px}.chip-dot{width:5px;height:5px;background:var(--pink);box-shadow:0 0 8px var(--pink);vertical-align:1px}.board-frame{position:relative;width:100%;aspect-ratio:1/1;max-height:calc(100vh - 230px);min-height:410px;background:#080d1e;border:1px solid #293454;box-shadow:0 0 0 5px rgba(29,38,72,.25),0 25px 70px #030510;overflow:hidden;border-radius:4px;touch-action:none}canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.board-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 70px rgba(4,7,18,.48),inset 0 0 0 1px rgba(98,231,236,.08)}.corner-tag{position:absolute;bottom:13px;right:13px;font-size:9px;color:#64718f;pointer-events:none}.corner-tag b{color:var(--cyan);font-weight:400}.screen-cover,.result-cover{position:absolute;inset:0;z-index:2;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;background:rgba(6,9,23,.78);backdrop-filter:blur(4px)}.screen-cover:before,.result-cover:before{content:'';position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,rgba(29,48,92,.35),transparent 66%)}.cover-orbit{position:relative;width:82px;height:82px;border:1px solid rgba(91,230,227,.25);border-radius:50%;margin-bottom:20px;box-shadow:0 0 25px rgba(44,211,212,.08),inset 0 0 24px rgba(44,211,212,.08)}.cover-orbit:before,.cover-orbit:after{content:'';position:absolute;background:rgba(91,230,227,.12);width:1px;height:112px;left:40px;top:-16px;transform:rotate(45deg)}.cover-orbit:after{transform:rotate(-45deg)}.cover-pac{width:38px;height:38px;background:var(--yellow);border-radius:50%;position:absolute;top:21px;left:21px;clip-path:polygon(0 0,100% 0,68% 50%,100% 100%,0 100%);filter:drop-shadow(0 0 12px #ffe666);z-index:1}.orbit-ghost{position:absolute;font-size:25px;z-index:2;text-shadow:0 0 12px currentColor}.ghost-pink{color:var(--pink);right:-7px;top:4px}.ghost-blue{color:#70aaff;left:-9px;bottom:2px}.cover-kicker{font:10px var(--mono);letter-spacing:.22em;color:var(--cyan);position:relative}.screen-cover h2,.result-cover h2{position:relative;font-size:clamp(28px,4vw,47px);line-height:1.04;letter-spacing:-.04em;margin:12px 0 12px}.screen-cover h2 span{color:var(--cyan)}.screen-cover p,.result-cover p{position:relative;color:#a0abc7;font-size:13px;line-height:1.65;margin:0 0 22px}.primary-btn{position:relative;border:0;border-radius:3px;background:var(--cyan);color:#07141a;font:700 11px var(--mono);letter-spacing:.12em;padding:15px 20px;min-width:190px;cursor:pointer;box-shadow:0 0 24px rgba(91,230,227,.19);transition:transform .15s,box-shadow .15s}.primary-btn:hover{transform:translateY(-2px);box-shadow:0 0 30px rgba(91,230,227,.42)}.primary-btn span{font-size:16px;margin-left:12px}.key-hint{position:relative;color:#687493;font-size:9px;letter-spacing:.12em;margin-top:18px}.key-hint span{color:var(--pink);padding:0 6px}.hidden{display:none!important}.pause-cover{position:absolute;z-index:3;inset:0;background:rgba(7,10,24,.76);backdrop-filter:blur(5px);display:flex;flex-direction:column;justify-content:center;align-items:center;gap:9px}.pause-symbol{font-size:32px;color:var(--cyan)}.pause-cover strong{font-size:26px;letter-spacing:.12em}.pause-cover span{color:#8792b0;font:10px var(--mono)}.result-cover{z-index:4}.result-cover h2{font-size:42px}.board-foot{height:42px;display:flex;align-items:center;justify-content:space-between;color:#697493;font-size:9px;letter-spacing:.1em}.board-foot b{color:#d9e3ff;font-weight:500}.tiny-dot{display:inline-block;width:5px;height:5px;border-radius:50%;background:var(--yellow);box-shadow:0 0 6px var(--yellow);margin-right:4px}.foot-center{color:#4d5878;font-size:8px;letter-spacing:.16em}.side-panel{background:linear-gradient(160deg,rgba(18,25,48,.94),rgba(12,17,34,.93));border:1px solid #232c47;border-radius:4px;padding:22px 20px 14px;display:flex;flex-direction:column;min-height:0;align-self:stretch}.stat-row{display:flex;justify-content:space-between;align-items:center}.stat-block strong{display:block;font:500 27px var(--mono);letter-spacing:.04em;margin-top:5px;color:#f8f7ff}.align-right{text-align:right}.lives{display:flex;gap:5px;margin-top:8px;color:var(--pink);font-size:16px;text-shadow:0 0 9px rgba(255,91,175,.5)}.lives .lost{color:#39415c;text-shadow:none}.divider{height:1px;background:#252e49;margin:18px 0}.memory-card{padding:2px 0 17px}.section-heading{display:flex;align-items:center;gap:8px;font-size:10px;color:#d4daf0;letter-spacing:.12em;font-weight:500}.pulse-icon{font-size:19px;color:var(--cyan);line-height:10px}.memory-live{margin-left:auto;color:var(--cyan);font-size:8px;letter-spacing:.12em}.memory-copy{font-size:11px;line-height:1.6;color:#7884a5;margin:12px 0 15px}.memory-copy b{font-weight:500;color:#b9c4e0}.memory-track{height:4px;background:#252d47;position:relative;border-radius:4px;overflow:visible}.memory-fill{width:0;height:100%;background:linear-gradient(90deg,#4ecbd5,#ff6bae);border-radius:4px;transition:width .4s}.memory-marker{position:absolute;right:0;top:-3px;width:1px;height:10px;background:#65708d}.memory-labels{display:flex;justify-content:space-between;margin-top:8px;font-size:7px;color:#67718f;letter-spacing:.09em}.memory-labels b{font-weight:400;color:var(--pink)}.memory-readout{display:flex;align-items:center;gap:7px;background:#0b1124;border:1px solid #202a45;border-radius:3px;padding:9px 8px;margin-top:14px;font-size:9px;color:#8995b5;letter-spacing:.025em;white-space:nowrap;overflow:hidden}.readout-dot{width:5px;height:5px;background:#596583;border-radius:50%;flex:none}.readout-dot.active{background:var(--pink);box-shadow:0 0 7px var(--pink)}.intel-card{border-top:1px solid #252e49;padding:16px 0 13px}.intel-icon{font-size:15px;color:var(--yellow)}.intel-line{display:flex;align-items:flex-start;gap:9px;font-size:9px;color:#8290b0;line-height:1.55;letter-spacing:0;margin-top:11px}.note-number{font-size:8px;color:#475472;letter-spacing:.08em}.controls-card{border-top:1px solid #252e49;padding:15px 0 13px;margin-top:auto}.controls-icon{font-size:15px;color:#b68cff}.control-row{display:flex;align-items:center;gap:6px;margin-top:12px;color:#687493;font-size:8px;letter-spacing:.08em}.keycaps{display:flex;gap:3px}.keycaps kbd,.space-key{font:9px var(--mono);color:#aab5d1;border:1px solid #35405e;border-bottom-width:2px;border-radius:3px;min-width:19px;text-align:center;padding:4px 4px;background:#151d34}.or{font-size:7px;color:#4f5b7c}.second-control{margin-top:11px}.space-key{min-width:52px;font-size:8px}.panel-bottom{display:flex;justify-content:space-between;border-top:1px solid #252e49;padding-top:13px;color:#57627f;font-size:7px;letter-spacing:.08em}.panel-bottom b{font-weight:400;color:#8b96b5}.panel-bottom i{font-style:normal;color:var(--cyan);font-size:11px;margin-left:3px}.mobile-pad{display:none}.footer{height:48px;border-top:1px solid rgba(115,132,191,.15);display:flex;align-items:center;justify-content:space-between;color:#4e5878;font-size:8px;letter-spacing:.13em}.footer-center{color:#7783a4}.footer b{font-size:11px;color:var(--cyan);margin-left:5px}
@media(max-width:1050px){.shell{padding:0 28px}.game-layout{grid-template-columns:minmax(0,1fr) 280px;gap:25px}.side-panel{padding:18px 16px 12px}.board-frame{min-height:360px}.topbar{height:70px}}
@media(max-width:760px){.shell{padding:0 15px}.topbar{height:58px}.brand{font-size:14px;gap:8px}.brand-mark{font-size:20px}.top-note{font-size:8px;letter-spacing:.09em}.separator{margin:0 4px}.sound-btn{padding:8px;font-size:8px}.sound-label{display:none}#soundIcon{padding:0}.game-layout{display:flex;flex-direction:column;gap:0;padding:16px 0 14px}.arena-head{margin-bottom:11px}.arena-title h1{font-size:21px}.level-chip{padding:7px 8px;font-size:8px}.board-frame{min-height:0;max-height:none;aspect-ratio:1/1;width:100%;box-shadow:0 0 0 3px rgba(29,38,72,.25),0 16px 42px #030510}.board-foot{height:32px;font-size:8px}.foot-center{display:none}.side-panel{margin-top:4px;display:grid;grid-template-columns:1fr 1fr;gap:0 14px;padding:14px;border-radius:4px}.stat-row{grid-column:1/-1}.stat-block strong{font-size:22px}.divider{grid-column:1/-1;margin:12px 0}.memory-card{grid-column:1/-1;padding-bottom:13px}.memory-copy{margin:9px 0 11px}.memory-readout{padding:7px;margin-top:10px}.intel-card{grid-column:1/-1;padding-top:13px;padding-bottom:11px}.intel-line{margin-top:8px}.controls-card{display:none}.panel-bottom{grid-column:1/-1;padding-top:11px;margin-top:9px}.mobile-pad{display:grid;grid-template-columns:repeat(3,46px);grid-template-rows:repeat(2,42px);gap:4px;justify-content:center;align-items:center;margin:15px auto 0;position:relative;touch-action:none}.pad-btn,.pad-pause{border:1px solid #35405e;background:linear-gradient(145deg,#17213b,#11192e);color:#95a5c9;border-radius:8px;font-size:13px;box-shadow:0 3px 0 #090f20;touch-action:none;-webkit-tap-highlight-color:transparent}.pad-btn:active,.pad-btn.pressed{background:#1b3c50;color:var(--cyan);border-color:#4bc8ce;transform:translateY(2px);box-shadow:0 1px 0 #090f20}.pad-up{grid-area:1/2}.pad-left{grid-area:2/1}.pad-down{grid-area:2/2}.pad-right{grid-area:2/3}.pad-pause{position:absolute;right:-65px;width:42px;height:38px;color:var(--pink);font-size:16px}.footer{height:38px;font-size:7px}.footer-center{display:none}.screen-cover h2{font-size:34px}.screen-cover p{font-size:11px;margin-bottom:17px}.cover-orbit{width:68px;height:68px;margin-bottom:16px}.cover-pac{top:16px;left:16px}.cover-orbit:before,.cover-orbit:after{left:33px;height:95px;top:-14px}.key-hint{font-size:8px}.primary-btn{padding:13px 15px;min-width:170px}.result-cover h2{font-size:34px}}
@media(max-width:380px){.shell{padding:0 10px}.top-note{display:none}.level-chip{font-size:7px}.board-foot{font-size:7px}.side-panel{padding:12px}.mobile-pad{grid-template-columns:42px 42px 42px;grid-template-rows:38px 38px}.pad-pause{right:-55px}.intel-line{font-size:8px}}
@media(min-width:761px) and (max-height:850px){.game-layout{padding-top:22px;padding-bottom:15px}.board-frame{max-height:calc(100vh - 190px);min-height:340px}.side-panel{padding-top:16px}.divider{margin:13px 0}.intel-line{margin-top:8px}.footer{height:40px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 19, H = 19, TILE = 32;
  const baseMap = [
    '###################',
    '#........#........#',
    '#.##.###.#.###.##.#',
    '#o##...........##o#',
    '#.##.#.###.###.##.#',
    '#....#...#...#....#',
    '####.###.#.###.####',
    '#......#...#......#',
    '#.##.#.#...#.#.##.#',
    '#....#.......#....#',
    '###.##.###.##.###.#',
    '#....#.......#....#',
    '#.##.#.#...#.#.##.#',
    '#....#...#...#....#',
    '####.#.#####.#.####',
    '#........#........#',
    '#.##.###.#.###.##.#',
    '#o...............o#',
    '###################'
  ];
  const dirs = {up:{x:0,y:-1}, down:{x:0,y:1}, left:{x:-1,y:0}, right:{x:1,y:0}};
  const reverse = {up:'down',down:'up',left:'right',right:'left'};
  const colors = ['#ff5baf','#6daaff','#ff9d55','#c28cff'];
  const state = {mode:'intro', score:0, high:loadHigh(), lives:3, level:1, dots:0, pellets:[], player:null, ghosts:[], route:new Map(), routeTotal:0, powered:0, shield:0, elapsed:0, clearTimer:0, lastTime:0, acc:0, sound:true, anim:0, particles:[]};
  let audio;
  const $ = id => document.getElementById(id);
  function loadHigh(){ try{return Number(localStorage.getItem('neonMazeHigh')||0)}catch(_){return 0} }
  function storeHigh(){ try{localStorage.setItem('neonMazeHigh',String(state.high))}catch(_){} }
  function resize(){
    const rect=canvas.getBoundingClientRect(), dpr=Math.min(window.devicePixelRatio||1,2);
    canvas.width=Math.max(1,Math.round(rect.width*dpr)); canvas.height=Math.max(1,Math.round(rect.height*dpr));
    ctx.setTransform(canvas.width/(W*TILE),0,0,canvas.height/(H*TILE),0,0);
    draw();
  }
  function isWall(x,y){ return x<0||y<0||x>=W||y>=H||baseMap[y][x]==='#'; }
  function open(x,y){return !isWall(x,y)}
  function makeActor(x,y,dir='left'){return {x,y,from:{x,y},to:{x,y},progress:1,dir,want:dir,step:0.14}}
  function spawnPoint(list){return list.map(([x,y])=>[x,y]).filter(([x,y])=>open(x,y))}
  function initLevel(){
    state.pellets=[]; state.dots=0; state.route.clear(); state.routeTotal=0; state.powered=0; state.elapsed=0;
    for(let y=0;y<H;y++) for(let x=0;x<W;x++){let cell=baseMap[y][x];if(cell==='.'||cell==='o'){state.pellets.push({x,y,power:cell==='o',taken:false});state.dots++}}
    state.player=makeActor(1,1,'right'); state.player.want='right';
    const starts=spawnPoint([[9,9],[8,9],[10,9],[9,8],[9,10],[7,9],[11,9]]);
    const count=Math.min(2+Math.floor((state.level+1)/2),4);
    state.ghosts=Array.from({length:count},(_,i)=>{const [x,y]=starts[i];return {...makeActor(x,y,'left'),color:colors[i],name:['PINK','BLUE','AMBER','VIOLET'][i],ai:i,flashed:0}});
    updateHud();
  }
  function activate(){
    if(state.mode==='intro'||state.mode==='over'||state.mode==='win'){
      if(state.mode==='over'||state.mode==='win'){state.score=0;state.lives=3;state.level=1;state.high=loadHigh()}
      initLevel(); state.mode='playing'; $('startScreen').classList.add('hidden');$('resultScreen').classList.add('hidden');$('pauseScreen').classList.add('hidden');
      sound('start'); state.lastTime=performance.now(); state.acc=0;
    }
  }
  function togglePause(){if(state.mode==='playing'){state.mode='paused';$('pauseScreen').classList.remove('hidden')}else if(state.mode==='paused'){state.mode='playing';$('pauseScreen').classList.add('hidden');state.lastTime=performance.now()}}
  function setDirection(name){if(!dirs[name])return;if(state.mode==='intro'||state.mode==='over'||state.mode==='win')activate();if(state.mode!=='playing')return;state.player.want=name}
  function addMemory(x,y){
    const key=x+','+y, value=(state.route.get(key)||0)+1; state.route.set(key,value);state.routeTotal++;
    // Smooth decay keeps memory responsive while retaining the paths that matter.
    if(state.routeTotal%70===0){for(const [k,v] of state.route){if(v<=1)state.route.delete(k);else state.route.set(k,v-1)}}
  }
  function nearestLearnedTarget(ghost){
    if(state.route.size<3)return {x:state.player.x,y:state.player.y};
    let best=null,bestScore=-Infinity;
    for(const [key,visits] of state.route){const [x,y]=key.split(',').map(Number);if(!open(x,y))continue;
      const distance=Math.abs(x-ghost.x)+Math.abs(y-ghost.y), playerDistance=Math.abs(x-state.player.x)+Math.abs(y-state.player.y);
      if(distance===0)continue;
      // Frequent route nodes attract the hunters; proximity to the current player breaks ties.
      const score=visits*1.7+Math.max(0,12-playerDistance)*.13-distance*.012;
      if(score>bestScore){bestScore=score;best={x,y}}
    }
    return best||{x:state.player.x,y:state.player.y};
  }
  function shortestFirstStep(sx,sy,tx,ty,ghost){
    const q=[[sx,sy,null]], seen=new Set([sx+','+sy]);let head=0;
    while(head<q.length){const [x,y,first]=q[head++];if(x===tx&&y===ty&&first)return first;
      const options=Object.entries(dirs).filter(([name,d])=>open(x+d.x,y+d.y));
      // Ghosts prefer not to reverse unless the maze forces them to.
      options.sort((a,b)=>{const aa=a[0]===reverse[ghost.dir]?1:0,bb=b[0]===reverse[ghost.dir]?1:0;return aa-bb});
      for(const [name,d] of options){const nx=x+d.x,ny=y+d.y,k=nx+','+ny;if(seen.has(k))continue;seen.add(k);q.push([nx,ny,first||name])}
    }
    return null;
  }
  function chooseGhostDir(g){
    let target;
    if(state.powered>0){ // scatter away from Pac-Man while a core is active
      const options=Object.entries(dirs).filter(([_,d])=>open(g.x+d.x,g.y+d.y));
      options.sort((a,b)=>{const da=Math.abs(g.x+a[1].x-state.player.x)+Math.abs(g.y+a[1].y-state.player.y);const db=Math.abs(g.x+b[1].x-state.player.x)+Math.abs(g.y+b[1].y-state.player.y);return db-da});
      return options[0]?.[0]||g.dir;
    }
    target=nearestLearnedTarget(g);
    // A little personality stops all hunters taking the exact same lane.
    if(g.ai===1){const d=dirs[state.player.dir];target={x:Math.max(1,Math.min(W-2,state.player.x+d.x*2)),y:Math.max(1,Math.min(H-2,state.player.y+d.y*2))};if(!open(target.x,target.y))target=nearestLearnedTarget(g)}
    if(g.ai===2&&Math.random()<.18)target={x:state.player.x,y:state.player.y};
    return shortestFirstStep(g.x,g.y,target.x,target.y,g)||g.dir;
  }
  function beginMove(actor,dir){const d=dirs[dir];if(!d||!open(actor.x+d.x,actor.y+d.y))return false;actor.from={x:actor.x,y:actor.y};actor.to={x:actor.x+d.x,y:actor.y+d.y};actor.progress=0;actor.dir=dir;return true}
  function movePlayer(dt){
    const p=state.player;
    if(p.progress<1){p.progress=Math.min(1,p.progress+dt/p.step);if(p.progress>=1){p.x=p.to.x;p.y=p.to.y;addMemory(p.x,p.y);eatAt(p.x,p.y)}return}
    if(p.want!==p.dir&&open(p.x+dirs[p.want].x,p.y+dirs[p.want].y)){beginMove(p,p.want);return}
    if(open(p.x+dirs[p.dir].x,p.y+dirs[p.dir].y))beginMove(p,p.dir);
  }
  function moveGhost(g,dt){
    if(g.progress<1){g.progress=Math.min(1,g.progress+dt/g.step);if(g.progress>=1){g.x=g.to.x;g.y=g.to.y}return}
    g.dir=chooseGhostDir(g); if(!beginMove(g,g.dir)){const viable=Object.entries(dirs).filter(([_,d])=>open(g.x+d.x,g.y+d.y)).map(([n])=>n);if(viable.length)beginMove(g,viable[Math.floor(Math.random()*viable.length)])}
  }
  function eatAt(x,y){
    const p=state.pellets.find(p=>!p.taken&&p.x===x&&p.y===y);if(!p)return;
    p.taken=true;state.dots--;state.score+=p.power?50:10;if(p.power){state.powered=7.4;sound('power');burst(x,y,'#ffe666',15)}else sound('dot');
    if(state.score>state.high){state.high=state.score;storeHigh()}
    updateHud();if(state.dots<=0){state.mode='clearing';state.clearTimer=1.5;sound('clear')}
  }
