[
  ".board-frame { position: relative; width: 100%; aspect-ratio: 1 / 1; max-height: calc(-230px + 100vh); min-height: 410px; background: rgb(8, 13, 30); border: 1px solid rgb(41, 52, 84); box-shadow: rgba(29, 38, 72, 0.25) 0px 0px 0px 5px, rgb(3, 5, 16) 0px 25px 70px; overflow: hidden; border-radius: 4px; touch-action: none; }",
  "@media (max-width: 1050px) {
  .shell { padding: 0px 28px; }
  .game-layout { grid-template-columns: minmax(0px, 1fr) 280px; gap: 25px; }
