}",
  "@media (max-width: 760px) {
  .shell { padding: 0px 15px; }
  .topbar { height: 58px; }
  .brand { font-size: 14px; gap: 8px; }
  .brand-mark { font-size: 20px; }
  .top-note { font-size: 8px; letter-spacing: 0.09em; }
  .separator { margin: 0px 4px; }
  .sound-btn { padding: 8px; font-size: 8px; }
  .sound-label { display: none; }
  #soundIcon { padding: 0px; }
  .game-layout { display: flex; flex-direction: column; gap: 0px; padding: 16px 0px 14px; }
  .arena-head { margin-bottom: 11px; }
  .arena-title h1 { font-size: 21px; }
  .level-chip { padding: 7px 8px; font-size: 8px; }
  .board-frame { min-height: 0px; max-height: none; aspect-ratio: 1 / 1; width: 100%; box-shadow: rgba(29, 38, 72, 0.25) 0px 0px 0px 3px, rgb(3, 5, 16) 0px 16px 42px; }
  .board-foot { height: 32px; font-size: 8px; }
  .foot-center { display: none; }
  .side-panel { margin-top: 4px; display: grid; grid-template-columns: 1fr 1fr; gap: 0px 14px; padding: 14px; border-radius: 4px; }
  .stat-row { grid-column: 1 / -1; }
  .stat-block strong { font-size: 22px; }
  .divider { grid-column: 1 / -1; margin: 12px 0px; }
  .memory-card { grid-column: 1 / -1; padding-bottom: 13px; }
  .memory-copy { margin: 9px 0px 11px; }
  .memory-readout { padding: 7px; margin-top: 10px; }
  .intel-card { grid-column: 1 / -1; padding-top: 13px; padding-bottom: 11px; }
  .intel-line { margin-top: 8px; }
  .controls-card { display: none; }
  .panel-bottom { grid-column: 1 / -1; padding-top: 11px; margin-top: 9px; }
  .mobile-pad { display: grid; grid-template-columns: repeat(3, 46px); grid-template-rows: repeat(2, 42px); gap: 4px; justify-content: center; align-items: center; margin: 15px auto 0px; position: relative; touch-action: none; }
  .pad-btn, .pad-pause { border: 1px solid rgb(53, 64, 94); background: linear-gradient(145deg, rgb(23, 33, 59), rgb(17, 25, 46)); color: rgb(149, 165, 201); border-radius: 8px; font-size: 13px; box-shadow: rgb(9, 15, 32) 0px 3px 0px; touch-action: none; -webkit-tap-highlight-color: transparent; }
  .pad-btn:active, .pad-btn.pressed { background: rgb(27, 60, 80); color: var(--cyan); border-color: rgb(75, 200, 206); transform: translateY(2px); box-shadow: rgb(9, 15, 32) 0px 1px 0px; }
  .pad-up { grid-area: 1 / 2; }
  .pad-left { grid-area: 2 / 1; }
  .pad-down { grid-area: 2 / 2; }
  .pad-right { grid-area: 2 / 3; }
  .pad-pause { position: absolute; right: -65px; width: 42px; height: 38px; color: var(--pink); font-size: 16px; }
  .footer { height: 38px; font-size: 7px; }
  .footer-center { display: none; }
  .screen-cover h2 { font-size: 34px; }
  .screen-cover p { font-size: 11px; margin-bottom: 17px; }
